import './layout.js';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const config = window.GOA_CONFIG || {};
const live = !!(config.supabaseUrl && config.supabaseKey && config.tripId);
const key = 'goa-afterglow-personal-v1';
const initial = () => ({trip:{title:'Our Goa escape',departure:'',start:'',end:'',budget:'',notes:''},entries:[],members:[],manual_crew:[],votes:[],files:[],expense_bills:[],agreement_required:false,agreement_version:'goa-crew-v1'});
let state;try{state = live ? initial() : JSON.parse(localStorage.getItem(key)) || initial()}catch{state=initial()}
let session = null, member = null, currentPage = 'overview', timer, refreshTimer, syncTimer;
let authMode='login',authError='',authBusy=false,authContact='',authName='',authMethod='whatsapp',authPhone='',otpPending=null;
const chat={messages:new Map(),presence:new Map(),presenceSignature:'',peerId:null,roomOpen:false,loaded:new Set(),loading:new Set(),socket:null,reconnectTimer:null,reconnectAttempts:0,lastEvent:0,readEvent:0,connected:false,draft:'',pendingFile:null,typing:false,typingTimer:null,unread:new Map()};
const chatIcon='<svg class="chat-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5.75A2.75 2.75 0 0 1 6.75 3h10.5A2.75 2.75 0 0 1 20 5.75v7.5A2.75 2.75 0 0 1 17.25 16H10l-4.7 3.7A.8.8 0 0 1 4 19.07V5.75Z"/><path d="M8 8h8M8 11.5h5.5"/></svg>';
const attachIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8.5 12.5 14 7a3 3 0 0 1 4.24 4.24l-7.07 7.07a5 5 0 0 1-7.07-7.07l7.43-7.42"/></svg>';
const tabs = [['overview','⌂','Overview'],['itinerary','◷','Itinerary'],['discussions',chatIcon,'Discussions'],['polls','▥','Polls & decisions'],['expenses','₹','Expenses'],['checklist','☑','Checklist'],['links','↗','Bookings'],['crew','♧','The crew'],['settings','⚙','Trip settings']];
const entries = kind => state.entries.filter(e => e.kind === kind).sort((a,b) => a.created_at.localeCompare(b.created_at));
const isAdmin = () => !live || member?.role === 'admin';
const canWrite = () => !live || !!member;
const mine = e => !live || e.author_id === session?.user?.id;
const money = n => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n)||0);
const shareMoney = n => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:0,maximumFractionDigits:2}).format(Number(n)||0);
const date = d => d ? new Date(d+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'}) : 'Not set';
const name = () => member?.display_name || session?.user?.display_name || 'You';
const expensePeople=()=>[...(state.members||[]).map(m=>({key:'account:'+m.user_id,id:m.user_id,kind:'account',display_name:m.display_name,is_self:m.user_id===session?.user?.id})),...(state.manual_crew||[]).map(m=>({key:'manual:'+m.id,id:m.id,kind:'manual',display_name:m.display_name,is_self:false}))].sort((a,b)=>a.display_name.localeCompare(b.display_name));
const crewCount=()=>Number(state.members?.length||0)+Number(state.manual_crew?.length||0);
const myExpenseKey=()=>{const id=session?.user?.id||state.members?.[0]?.user_id;return id?'account:'+id:''};
function expenseShareModel(){const key=myExpenseKey(),list=entries('expense'),items=list.flatMap(e=>{const split=Array.isArray(e.data.split_with)?e.data.split_with:[],included=split.some(person=>person.key===key);return included&&split.length?[{entry:e,split,share:Number(e.data.amount||0)/split.length}]:[]});return{key,items,total:items.reduce((sum,item)=>sum+item.share,0),tripTotal:list.reduce((sum,e)=>sum+Number(e.data.amount||0),0),untracked:list.filter(e=>!Array.isArray(e.data.split_with)||!e.data.split_with.length).length}}
function expensePayerName(entry,people=new Map(expensePeople().map(person=>[person.key,person]))){return people.get(entry.data.payer_key)?.display_name||state.members.find(person=>person.user_id===entry.data.payer_id)?.display_name||entry.data.payer||'Crew member'}
function showMyExpenseBreakdown(){const model=expenseShareModel();const rows=model.items.map(({entry,split,share})=>`<article class="expense-share-detail"><div><strong>${esc(entry.data.title||'Trip expense')}</strong><small>Paid by ${esc(expensePayerName(entry))} · split between ${split.length} ${split.length===1?'person':'people'}</small></div><span><small>Expense ${money(entry.data.amount)}</small><strong>${shareMoney(share)}</strong></span></article>`).join('');openModal('Your expense share',`<div class="expense-share-modal-summary"><div><small>Total trip expense</small><strong>${money(model.tripTotal)}</strong></div><div><small>Your share</small><strong>${shareMoney(model.total)}</strong></div></div>${rows?`<div class="expense-share-details">${rows}</div>`:'<div class="expense-share-empty"><span>₹</span><strong>No expenses are assigned to you yet.</strong><p>Your detailed share will appear after an expense is split with you.</p></div>'}${model.untracked?`<p class="note">${model.untracked} older ${model.untracked===1?'expense is':'expenses are'} excluded because no split was recorded.</p>`:''}<div class="form-actions"><button class="button" data-close>Done</button></div>`)}
function expensesV2(){const list=entries('expense'),bills=new Map((state.expense_bills||[]).map(b=>[b.entry_id,b])),people=new Map(expensePeople().map(p=>[p.key,p])),model=expenseShareModel(),paid={};list.forEach(entry=>{const payer=expensePayerName(entry,people);paid[payer]=(paid[payer]||0)+Number(entry.data.amount)});return intro('LESS MATHS. MORE MOMENTS.','Keep tabs. Keep it easy.','See the complete trip spend, your own share, and every item behind the total.',`<button class="button" data-action="add-expense">＋ Add expense</button>`)+`<div class="expense-summary-grid"><section class="panel expense-summary-card"><div class="eyebrow">TOTAL TRIP EXPENSE</div><div class="summary-total">${money(model.tripTotal)}</div><p class="muted">${state.trip.budget?'Trip target: '+money(state.trip.budget):'All shared expenses logged for this trip.'}</p></section><button type="button" class="panel expense-summary-card expense-my-share" data-my-expense-breakdown aria-haspopup="dialog"><span class="eyebrow">YOUR SHARE</span><span class="summary-total">${shareMoney(model.total)}</span><span class="muted">Tap for the detailed breakup <b>↗</b></span></button></div><section class="panel expense-paid-panel"><div class="eyebrow">PAID BY</div>${Object.keys(paid).length?Object.entries(paid).map(([payer,amount])=>`<div class="row expense-paid-row"><span class="avatar">${esc(payer[0]||'₹')}</span><span class="row-main">${esc(payer)}</span><strong>${money(amount)}</strong></div>`).join(''):'<p class="intro-note">Your shared spending will appear here.</p>'}</section><section class="panel expense-list">${list.length?list.map(entry=>{const bill=bills.get(entry.id),previewable=bill&&/^(image\/|application\/pdf|text\/|application\/json)/.test(bill.mime_type||''),split=Array.isArray(entry.data.split_with)?entry.data.split_with:[],share=split.length?Number(entry.data.amount)/split.length:0;return `<article class="row expense-row"><span class="stat-icon">₹</span><div class="row-main"><h3>${esc(entry.data.title)}</h3><p>Paid by ${esc(expensePayerName(entry,people))}${entry.data.notes?' · '+esc(entry.data.notes):''}</p>${split.length?`<div class="expense-split-summary"><strong>Split with ${split.length===crewCount()?'everyone':split.length+' '+(split.length===1?'person':'people')} · ${shareMoney(share)} each</strong><span>${split.map(person=>esc(person.name)).join(', ')}</span></div>`:'<div class="expense-split-summary unsplit"><strong>Split not recorded</strong><span>This expense was added before split tracking.</span></div>'}${bill?`<div class="expense-bill"><span class="expense-file-icon">${bill.mime_type?.startsWith('image/')?'▧':'↗'}</span><span><strong>${esc(bill.name)}</strong><small>${fileSize(Number(bill.size_bytes)||0)}</small></span>${previewable?`<button type="button" class="text-link" data-expense-preview="${entry.id}">Preview</button>`:''}<button type="button" class="text-link" data-expense-download="${entry.id}">Download</button></div>`:''}</div><strong class="expense-amount">${money(entry.data.amount)}</strong>${deleteButton(entry)}</article>`}).join(''):empty('₹','A clean slate.','Add costs as they happen: travel, stays, food, and everything in between.','Log an expense','add-expense')}</section><p class="note">Splits are recorded for planning only. The app does not collect payments or settle balances.</p>`}
expenses=expensesV2;
function pollsV2(){const list=entries('poll');return intro('FEWER MAYBES, MORE MEMORIES','Good ideas. Group decisions.','Create clear choices, let the crew vote, and optionally collect their own ideas.',`<button class="button" data-action="add-poll">＋ Create a poll</button>`)+`${list.length?list.map(entry=>{const votes=state.votes.filter(vote=>vote.entry_id===entry.id),own=votes.find(vote=>vote.user_id===(session?.user?.id||'local')),options=Array.isArray(entry.data.options)?entry.data.options:[];return `<section class="panel poll-card"><div class="panel-head"><div><h2>${esc(entry.data.title)}</h2>${entry.data.allow_other?'<p class="poll-open-note">Crew suggestions are open</p>':''}</div>${deleteButton(entry)}</div><div class="poll-options">${options.map((option,index)=>{const count=votes.filter(vote=>vote.option_index===index).length,selected=own?.option_index===index;return `<button class="poll-option ${selected?'selected':''}" data-vote="${entry.id}" data-option="${index}" aria-pressed="${selected}"><span class="poll-fill" style="width:${votes.length?count/votes.length*100:0}%"></span><span>${esc(option)} ${selected?'✓':''}</span><span>${count} vote${count!==1?'s':''}</span></button>`}).join('')}</div>${entry.data.allow_other?`<form class="poll-custom-answer" data-poll-custom="${entry.id}"><label for="poll-other-${entry.id}">Have another idea?</label><div><input id="poll-other-${entry.id}" name="answer" type="text" maxlength="100" placeholder="Type what you have in mind…" required><button class="button light" type="submit">Add &amp; vote</button></div></form>`:''}<p class="note">${votes.length} crew member${votes.length!==1?'s':''} voted${entry.data.allow_other?' · custom answers become choices for everyone':''}</p></section>`}).join(''):`<section class="panel">${empty('▥','Decisions are better together.','Create a poll with separate choices, or let the crew suggest their own answers.','Create a poll','add-poll')}</section>`}`}
polls=pollsV2;
async function customPollVote(id,answer){const clean=String(answer||'').trim().replace(/\s+/g,' ');if(!clean||clean.length>100)throw Error('Enter an answer using 1 to 100 characters.');const uid=session?.user?.id||'local';if(live){await api('pollCustomVote',{id,answer:clean});await sync()}else{const entry=state.entries.find(item=>item.id===id&&item.kind==='poll');if(!entry?.data.allow_other)throw Error('This poll does not accept new answers.');let index=entry.data.options.findIndex(option=>option.toLowerCase()===clean.toLowerCase());if(index<0){if(entry.data.options.length>=20)throw Error('This poll already has the maximum number of answers.');entry.data.options.push(clean);index=entry.data.options.length-1}state.votes=state.votes.filter(vote=>!(vote.entry_id===id&&vote.user_id===uid));state.votes.push({entry_id:id,user_id:uid,option_index:index});persist();render()}toast('Your answer was added and your vote was counted.')}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function persist(){if(!live)localStorage.setItem(key,JSON.stringify(state))}
async function api(action,data={}){
 const r=await fetch(config.supabaseUrl+'/functions/v1/goa-trip-api',{method:'POST',headers:{apikey:config.supabaseKey,'Content-Type':'application/json',...(session?.access_token?{Authorization:'Bearer '+session.access_token}:{})},body:JSON.stringify({action,data})});
 const value=await r.json().catch(()=>({error:'The server could not complete the request.'}));
 if(!r.ok){if(r.status===401&&session){saveSession(null);member=null;state=initial();render()}throw Error(value.error||'Request failed');}return value;
}
function saveSession(value){session=value;if(value)localStorage.setItem('goa-custom-session-v3',JSON.stringify(value));else localStorage.removeItem('goa-custom-session-v3');sessionStorage.removeItem('goa-custom-session-v2')}
async function sync(){if(!live||!session)return false;const next=await api('get'),nextMember=next.members.find(m=>m.user_id===session.user.id)||null,changed=JSON.stringify(next)!==JSON.stringify(state)||nextMember?.role!==member?.role;state=next;member=nextMember;if(member&&!state.agreement_required)connectChat();else disconnectChat();if(changed)render();else refreshPresenceUI();return changed}
async function addEntry(kind,data){if(!canWrite())return openAccount();if(live){await api('add',{kind,data});await sync()}else{state.entries.push({id:crypto.randomUUID(),kind,data,author_id:'local',created_at:new Date().toISOString()});persist();render()}toast('Added to the trip.')}
async function updateEntry(e,data){if(live){await api('update',{id:e.id,data});await sync()}else{e.data=data;persist();render()}}
async function removeEntry(id){const e=state.entries.find(x=>x.id===id);if(!e)return;openModal('Remove this item?',`<p class="modal-note">Remove “${esc(e.data.title||e.data.text||'this item')}” from the trip?</p><div class="form-actions"><button class="button outline" data-close>Keep it</button><button class="button danger" id="confirm-remove">Remove item</button></div>`);$('#confirm-remove').onclick=()=>run(async()=>{if(live){await api('delete',{id});await sync()}else{state.entries=state.entries.filter(e=>e.id!==id);state.votes=state.votes.filter(v=>v.entry_id!==id);persist();render()}closeModal();toast('Item removed.')})}

const chatKey=peer=>peer||'group';
const chatMember=id=>state.members.find(m=>m.user_id===id);
function chatPresence(id){return chat.presence.get(id)||{user_id:id,display_name:chatMember(id)?.display_name||'Crew member',active:false,typing_group:false,typing_peer_id:null}}
function conversationMessages(peer=chat.peerId){return [...chat.messages.values()].filter(m=>peer?m.recipient_id&&((m.sender_id===session?.user?.id&&m.recipient_id===peer)||(m.sender_id===peer&&m.recipient_id===session?.user?.id)):!m.recipient_id).sort((a,b)=>Number(a.id)-Number(b.id))}
function mergeChatMessages(messages=[]){let changed=false;for(const message of messages){const key=String(message.id),before=chat.messages.get(key),next={...before,...message};if(!before||JSON.stringify(before)!==JSON.stringify(next)){chat.messages.set(key,next);changed=true}}return changed}
function chatTypingText(){const mine=session?.user?.id;if(chat.peerId){const p=chatPresence(chat.peerId);return p.typing_peer_id===mine?`${p.display_name} is typing…`:''}const names=[...chat.presence.values()].filter(p=>p.user_id!==mine&&p.typing_group).map(p=>p.display_name);if(!names.length)return '';if(names.length===1)return `${names[0]} is typing…`;if(names.length===2)return `${names[0]} and ${names[1]} are typing…`;return `${names[0]}, ${names[1]} and ${names.length-2} others are typing…`}
function refreshPresenceUI(){document.querySelectorAll('[data-presence-id]').forEach(el=>{const p=chatPresence(el.dataset.presenceId);if(el.dataset.presenceKind==='dot')el.classList.toggle('active',!!p.active);else el.textContent=p.active?'Active now':'Offline'});const typing=$('#typing-indicator');if(typing)typing.textContent=chatTypingText();const status=$('#chat-live-status');if(status){status.textContent=chat.connected?'Live':'Reconnecting…';status.classList.toggle('offline',!chat.connected)}}
function chatReadKey(){return session?.user?.id?'goa-chat-read-'+session.user.id:''}
function markChatRead(){chat.readEvent=Math.max(chat.readEvent,chat.lastEvent);const key=chatReadKey();if(key)localStorage.setItem(key,String(chat.readEvent));chat.unread.clear();renderChatBubble()}
function applyChatEvents(events=[]){let changed=false;for(const event of events){const message=event.message;if(!message)continue;changed=mergeChatMessages([message])||changed;const eventId=Number(event.event_id||event.id||0);if(event.type==='message'&&message.sender_id!==session?.user?.id&&eventId>chat.readEvent){const key=chatKey(message.recipient_id?(message.sender_id===session?.user?.id?message.recipient_id:message.sender_id):null),visible=currentPage==='discussions'&&chatKey(chat.peerId)===key&&!document.hidden;if(visible){chat.readEvent=Math.max(chat.readEvent,eventId);const readKey=chatReadKey();if(readKey)localStorage.setItem(readKey,String(chat.readEvent))}else chat.unread.set(key,(chat.unread.get(key)||0)+1)}}return changed}
function scheduleChatReconnect(){clearTimeout(chat.reconnectTimer);if(!session||!member||document.hidden)return;const wait=Math.min(15000,750*2**Math.min(chat.reconnectAttempts++,5));chat.reconnectTimer=setTimeout(connectChat,wait)}
function disconnectChat(){chat.manualClose=true;clearTimeout(chat.reconnectTimer);clearTimeout(chat.typingTimer);chat.typing=false;chat.connected=false;if(chat.socket){try{chat.socket.close(1000,'Signed out')}catch{}chat.socket=null}refreshPresenceUI()}
function connectChat(){if(!live||!session?.access_token||!member||document.hidden)return;if(chat.socket&&chat.socket.readyState<2)return;const eventKey='goa-chat-event-'+session.user.id;if(chat.eventKey!==eventKey){chat.eventKey=eventKey;chat.lastEvent=Number(sessionStorage.getItem(eventKey)||0);chat.readEvent=Number(localStorage.getItem(chatReadKey())||0);chat.messages.clear();chat.presence.clear();chat.loaded.clear();chat.unread.clear()}chat.manualClose=false;const url=new URL(config.supabaseUrl.replace(/^http/,'ws')+'/functions/v1/goa-trip-api');url.searchParams.set('apikey',config.supabaseKey);url.searchParams.set('after',String(chat.lastEvent));const socket=new WebSocket(url,['goa-chat-v1','session.'+session.access_token]);chat.socket=socket;socket.onopen=()=>{chat.connected=true;chat.reconnectAttempts=0;refreshPresenceUI()};socket.onmessage=event=>{let update;try{update=JSON.parse(event.data)}catch{return}if(update.type==='sync'){chat.lastEvent=Math.max(chat.lastEvent,Number(update.last_event_id||0));sessionStorage.setItem(chat.eventKey,String(chat.lastEvent));const presence=Array.isArray(update.presence)?update.presence:[],signature=JSON.stringify(presence);const presenceChanged=signature!==chat.presenceSignature;if(presenceChanged){chat.presenceSignature=signature;chat.presence=new Map(presence.map(p=>[p.user_id,p]))}const messageChanged=applyChatEvents(update.events||[]);if(messageChanged&&['discussions'].includes(currentPage))render();else{if(messageChanged)renderNav();if(presenceChanged)refreshPresenceUI()}}else if(update.type==='ready'){chat.connected=true;refreshPresenceUI()}else if(update.type==='error')toast(update.message||'Live chat is reconnecting.')};socket.onclose=()=>{if(chat.socket===socket)chat.socket=null;chat.connected=false;refreshPresenceUI();if(!chat.manualClose)scheduleChatReconnect()};socket.onerror=()=>{chat.connected=false;refreshPresenceUI()}}
function sendTyping(value){clearTimeout(chat.typingTimer);if(chat.typing!==value){chat.typing=value;if(chat.socket?.readyState===WebSocket.OPEN)chat.socket.send(JSON.stringify({type:'typing',typing:value,peer_id:chat.peerId}))}if(value)chat.typingTimer=setTimeout(()=>sendTyping(false),1400)}
async function ensureChatHistory(peer=chat.peerId){if(!live)return;const key=chatKey(peer);if(chat.loaded.has(key)||chat.loading.has(key))return;chat.loading.add(key);try{const result=await api('chatHistory',{peer_id:peer});mergeChatMessages(result.messages||[]);chat.loaded.add(key);if(currentPage==='discussions'&&chatKey(chat.peerId)===key)render()}catch(error){toast(error.message)}finally{chat.loading.delete(key)}}
function openChat(peer=null){sendTyping(false);chat.peerId=peer||null;chat.roomOpen=true;chat.draft='';chat.pendingFile=null;markChatRead();if(location.hash!=='#discussions')location.hash='discussions';else render()}
function openChatList(){sendTyping(false);chat.peerId=null;chat.roomOpen=false;chat.draft='';chat.pendingFile=null;markChatRead();if(location.hash!=='#discussions')location.hash='discussions';else render()}
function removeChatMessage(id){const message=chat.messages.get(String(id));if(!message)return;openModal('Remove this message?',`<p class="modal-note">This message will be replaced with “Message removed” for everyone in this conversation.</p><div class="form-actions"><button class="button outline" data-close>Keep message</button><button class="button danger" id="confirm-remove">Remove message</button></div>`);$('#confirm-remove').onclick=()=>run(async()=>{const result=await api('chatDelete',{id});mergeChatMessages([{...message,deleted_at:result.deleted_at,body:null}]);chat.lastEvent=Math.max(chat.lastEvent,Number(result.event_id||0));closeModal();render();toast('Message removed.')})}
const fileSize=n=>n>=1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
function chatMessageHtml(message){const own=message.sender_id===session?.user?.id,canDelete=!message.deleted_at&&(own||(isAdmin()&&!message.recipient_id)),previewable=/^(image\/|application\/pdf|text\/|application\/json)/.test(message.attachment_mime||''),attachment=message.attachment_name&&!message.deleted_at?`<div class="chat-attachment"><span class="chat-file-icon">${message.attachment_mime?.startsWith('image/')?'▧':'↗'}</span><span class="chat-file-info"><strong>${esc(message.attachment_name)}</strong><small>${esc(fileSize(Number(message.attachment_size)||0))}</small></span>${previewable?`<button type="button" class="chat-file-action" data-chat-preview="${message.id}">Preview</button>`:''}<button type="button" class="chat-file-action" data-chat-download="${message.id}">Download</button></div>`:'';return `<article class="message ${own?'mine':''} ${message.deleted_at?'removed':''}"><div class="author">${esc(message.sender_name||'Crew member')}</div>${message.deleted_at?'<p><em>Message removed</em></p>':`${message.body?`<p>${esc(message.body)}</p>`:''}${attachment}`}<time>${new Date(message.created_at).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time>${canDelete?`<button class="delete-button chat-delete" data-chat-delete="${message.id}" aria-label="Remove message">×</button>`:''}</article>`}

const storageConsentKey='goa-essential-storage-consent-v1';
function showStorageConsent(){
 if(state.agreement_required||localStorage.getItem(storageConsentKey)||$('#storage-consent'))return;
 document.body.insertAdjacentHTML('beforeend',`<section id="storage-consent" class="storage-consent" role="dialog" aria-modal="true" aria-labelledby="storage-consent-title"><div><span class="storage-consent-icon">✓</span><div><h2 id="storage-consent-title">Essential device storage</h2><p>This trip app needs secure device storage to keep you signed in, remember your preferences, and restore your trip safely. We do not use advertising or tracking cookies.</p><button type="button" id="storage-details">Why accepting is important</button></div></div><button type="button" class="button" id="storage-accept">Accept &amp; continue</button></section>`);
 $('#storage-accept').onclick=()=>{localStorage.setItem(storageConsentKey,new Date().toISOString());$('#storage-consent').remove();toast('Essential storage accepted.')};
 $('#storage-details').onclick=()=>openModal('Why device storage is needed','<p class="modal-note">The app stores your private session on this device so you do not need a new WhatsApp code every time. It also remembers installation, notification, accessibility, and display preferences. Without this storage, sign-in and the installed app cannot work reliably.</p><p class="modal-note">Trip records, messages, accounts, and files remain protected on the server. This notice covers essential app storage only—there are no advertising or cross-site tracking cookies.</p><div class="form-actions"><button class="button" data-close>Understood</button></div>');
}

function showTripAgreement(){
 if(!state.agreement_required||$('#trip-agreement'))return;
 const overlay=document.createElement('section');overlay.id='trip-agreement';overlay.className='agreement-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-labelledby','agreement-title');
 overlay.innerHTML=`<div class="agreement-card"><div class="agreement-hero"><span>✳</span><div><div class="eyebrow">WELCOME TO GOA AFTERGLOW</div><h1 id="agreement-title">You’re officially part of the crew! 🌴</h1><p>This is our private space to plan the trip, share ideas, chat, vote, track expenses, and keep everything together.</p></div></div><form id="agreement-form"><section><h2>What happens here stays with the crew</h2><p>Please keep trip conversations, personal details, photos, phone numbers, bookings, and plans within the invited group unless everyone concerned agrees to share them.</p><p>Be respectful, protect each other’s privacy, and remember—we’re here to make good memories together.</p></section><section><h2>A few friendly trip rules</h2><ul><li>Be kind and respectful to everyone.</li><li>Plans can change—keep suggestions flexible.</li><li>Respond to important polls and confirmations on time.</li><li>Record shared expenses clearly and honestly.</li><li>Do not share another member’s personal information or photos without permission.</li><li>Raise safety, health, travel, or accommodation concerns early.</li><li>Keep the group fun, helpful, and drama-free.</li></ul></section><section><h2>App permissions</h2><div class="permission-note"><strong>Essential device storage <span>Required</span></strong><p>Keeps you signed in, remembers your preferences, restores your trip session, and helps the installed app work reliably. It is not used for advertising or cross-site tracking.</p></div><div class="permission-note"><strong>Notifications <span class="optional">Recommended</span></strong><p>Get new messages, direct messages, polls, itinerary changes, files, and important trip updates. You can disable these later.</p></div><div class="permission-note"><strong>Photos, files and camera <span class="optional">Optional</span></strong><p>Requested only when you choose to upload or take something. The app never opens them without your action.</p></div></section><section class="agreement-checks"><h2>Your agreement</h2><label><input type="checkbox" name="privacy" required><span>I agree to respect the privacy of the crew and follow the trip guidelines.</span></label><label><input type="checkbox" name="storage" required><span>I accept the essential device storage required for sign-in and app operation.</span></label><label><input type="checkbox" name="notifications"><span>Enable notifications for trip updates and messages. <small>Optional but recommended</small></span></label><div id="agreement-error" class="error" role="alert" hidden></div><button class="button agreement-accept" type="submit">Accept &amp; enter the trip ↗</button><p class="note">You can review these details later from Trip Settings.</p></section></form></div>`;
 document.body.appendChild(overlay);
 $('#agreement-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type="submit"]'),error=$('#agreement-error'),data=new FormData(form);button.disabled=true;error.hidden=true;(async()=>{try{const wantsNotifications=data.get('notifications')==='on';await api('acceptAgreement',{agreement_version:state.agreement_version||'goa-crew-v1',privacy_accepted:true,essential_storage_accepted:true,notifications_requested:wantsNotifications});localStorage.setItem(storageConsentKey,new Date().toISOString());overlay.remove();await sync();if(wantsNotifications)window.GOA_PWA?.enableNotifications?.()}catch(err){error.textContent=err.message;error.hidden=false;button.disabled=false}})()};
}

function openModal(title,html){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-close aria-label="Close dialog">×</button></div>${html}`;if(!$('#modal').open)$('#modal').showModal();$('#modal-content').querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal)}
function closeModal(){$('#modal').querySelectorAll('input[type=password]').forEach(i=>i.value='');const modal=$('#modal'),url=modal.dataset.objectUrl,selectionUrl=modal.dataset.selectionUrl;if(url)URL.revokeObjectURL(url);if(selectionUrl)URL.revokeObjectURL(selectionUrl);delete modal.dataset.objectUrl;delete modal.dataset.selectionUrl;modal.close()}
async function run(fn){const buttons=[...$('#modal').querySelectorAll('button[type="submit"],#confirm-remove')];buttons.forEach(b=>b.disabled=true);try{await fn()}catch(e){toast(e.message)}finally{buttons.forEach(b=>b.disabled=false)}}
function form(title,fields,onSubmit,note=''){openModal(title,`${note?`<p class="modal-note">${esc(note)}</p>`:''}<form id="edit-form">${fields}<div class="form-actions"><button type="button" class="button outline" data-close>Cancel</button><button class="button" type="submit">Save ${title.startsWith('Create poll')?'poll':'details'} ↗</button></div></form>`);$('#edit-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));run(async()=>{await onSubmit(values);closeModal()})}}
const field=(label,key,type='text',value='',required=false)=>`<label for="field-${key}">${esc(label)}</label><input id="field-${key}" name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" max="999999999" step="0.01"':''} maxlength="${type==='text'?'300':'1000'}">`;
const area=(label,key,value='')=>`<label for="field-${key}">${esc(label)}</label><textarea id="field-${key}" name="${key}" maxlength="10000">${esc(value)}</textarea>`;
function addExpenseForm(){const people=expensePeople(),self='account:'+(session?.user?.id||state.members?.[0]?.user_id||'');if(!people.length)return toast('Add a crew member before adding an expense.');openModal('Add an expense',`<p class="modal-note">Choose who paid, who shares this expense, and optionally attach the bill.</p><form id="expense-form">${field('What was it for?','title','text','',true)}${field('Amount (INR)','amount','number','',true)}<label for="expense-payer">Paid by</label><select id="expense-payer" name="payer_key" required>${people.map(p=>`<option value="${p.key}" ${p.key===self?'selected':''}>${esc(p.display_name)}${p.is_self?' · You':p.kind==='manual'?' · Expense-only crew':''}</option>`).join('')}</select><fieldset class="expense-split-fieldset"><legend>Split with</legend><label class="expense-split-all"><input id="expense-split-all" type="checkbox" checked><span><strong>Everyone</strong><small>Select or clear the full crew</small></span></label><div class="expense-split-grid">${people.map(p=>`<label class="expense-split-person"><input type="checkbox" name="split_keys" value="${p.key}" checked><span>${esc(p.display_name)}${p.is_self?' · You':p.kind==='manual'?' · Expense-only':''}</span></label>`).join('')}</div></fieldset>${area('Notes','notes')}<label for="expense-bill">Bill or receipt <span class="optional-label">Optional</span></label><input id="expense-bill" name="bill" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,.heic,.txt,.csv,.json,.docx,.xlsx"><p class="note">PDF, image, text, Word, or Excel · Maximum 10 MB</p><div id="expense-file-preview" class="expense-file-preview" hidden></div><div class="form-actions"><button type="button" class="button outline" data-close>Cancel</button><button class="button" type="submit">Save expense ↗</button></div></form>`);const formEl=$('#expense-form'),fileEl=$('#expense-bill'),preview=$('#expense-file-preview'),all=$('#expense-split-all'),checks=[...formEl.querySelectorAll('input[name="split_keys"]')];all.onchange=()=>checks.forEach(input=>input.checked=all.checked);checks.forEach(input=>input.onchange=()=>{all.checked=checks.every(item=>item.checked);all.indeterminate=!all.checked&&checks.some(item=>item.checked)});fileEl.onchange=()=>{const file=fileEl.files[0],modal=$('#modal');const old=modal.dataset.selectionUrl;if(old)URL.revokeObjectURL(old);delete modal.dataset.selectionUrl;if(!file){preview.hidden=true;preview.innerHTML='';return}if(file.size>10485760){fileEl.value='';toast('Choose a bill no larger than 10 MB.');return}let visual='<span class="expense-file-icon">↗</span>';if(file.type.startsWith('image/')){const url=URL.createObjectURL(file);modal.dataset.selectionUrl=url;visual=`<img src="${url}" alt="Selected bill preview">`}preview.innerHTML=`${visual}<span><strong>${esc(file.name)}</strong><small>${fileSize(file.size)} · Ready to attach</small></span>`;preview.hidden=false};formEl.onsubmit=e=>{e.preventDefault();run(async()=>{const values=new FormData(formEl),amount=Number(values.get('amount')),split_keys=checks.filter(input=>input.checked).map(input=>input.value);if(amount<=0)throw Error('Enter an amount greater than zero.');if(!split_keys.length)throw Error('Choose at least one person for the split.');const file=fileEl.files[0];if(file&&file.size>10485760)throw Error('Choose a bill no larger than 10 MB.');const data={title:String(values.get('title')||'').trim(),amount,payer_key:String(values.get('payer_key')||''),split_keys,notes:String(values.get('notes')||'').trim()};if(live){const attachment=file?{name:file.name,mime_type:chatMime(file),base64:await fileBase64(file)}:null;await api('addExpense',{...data,attachment});await sync()}else{const payer=people.find(p=>p.key===data.payer_key),split_with=split_keys.map(key=>people.find(p=>p.key===key)).filter(Boolean).map(p=>({key:p.key,kind:p.kind,name:p.display_name}));state.entries.push({id:crypto.randomUUID(),kind:'expense',data:{...data,payer:payer?.display_name||name(),payer_kind:payer?.kind,split_with,split_count:split_with.length},author_id:'local',created_at:new Date().toISOString()});persist();render()}closeModal();toast(file?'Expense, split, and bill added.':'Expense split added.')})}}
function addPollForm(){openModal('Create poll',`<p class="modal-note">Add clear choices one at a time. You can also let the crew suggest an answer of their own.</p><form id="poll-form">${field('What should we decide?','title','text','',true)}<fieldset class="poll-option-fieldset"><legend>Poll options</legend><div id="poll-option-fields"></div><button type="button" class="button light poll-add-option" id="poll-add-option">＋ Add another option</button></fieldset><label class="poll-other-toggle"><input type="checkbox" name="allow_other"><span><strong>Let people add their own answer</strong><small>Crew members can type an idea and vote for it.</small></span></label><div class="form-actions"><button type="button" class="button outline" data-close>Cancel</button><button class="button" type="submit">Save poll ↗</button></div></form>`);const formEl=$('#poll-form'),fields=$('#poll-option-fields'),addButton=$('#poll-add-option');const refresh=()=>{const rows=[...fields.children];rows.forEach(row=>{row.querySelector('.poll-remove-option').hidden=rows.length<=2});addButton.disabled=rows.length>=10};const addOption=(value='')=>{const row=document.createElement('div');row.className='poll-option-field';row.innerHTML=`<input name="poll_option" type="text" maxlength="100" placeholder="Option ${fields.children.length+1}" value="${esc(value)}" required><button type="button" class="poll-remove-option" aria-label="Remove this option">×</button>`;row.querySelector('button').onclick=()=>{row.remove();[...fields.querySelectorAll('input')].forEach((input,index)=>input.placeholder=`Option ${index+1}`);refresh()};fields.appendChild(row);refresh()};addOption();addOption();addButton.onclick=()=>{addOption();fields.lastElementChild.querySelector('input').focus()};formEl.onsubmit=e=>{e.preventDefault();run(async()=>{const values=new FormData(formEl),options=[...new Set(values.getAll('poll_option').map(value=>String(value).trim()).filter(Boolean))];if(options.length<2||options.length>10)throw Error('Add between 2 and 10 different options.');await addEntry('poll',{title:String(values.get('title')||'').trim(),options,allow_other:values.get('allow_other')==='on'});closeModal()})}}
function addForm(kind){if(!canWrite())return openAccount();if(kind==='expense')return addExpenseForm();if(kind==='poll')return addPollForm();const forms={
 itinerary:['Add a plan',field('What’s the plan?','title','text','',true)+`<div class="field-pair">${field('Date','date','date')}${field('Time','time','time')}</div>`+field('Location','location')+area('Notes','notes'),async v=>{await addEntry(kind,v)}],
 checklist:['Add a checklist item',field('What needs doing or packing?','title','text','',true)+field('Who’s taking care of it?','assignee')+`<label for="field-category">Category</label><select id="field-category" name="category"><option>To do</option><option>Packing</option><option>Before departure</option></select>`,async v=>{await addEntry(kind,{...v,done:false})}],
 link:['Add a useful link',field('Title','title','text','',true)+field('Website link','url','url','',true)+`<label for="field-category">Category</label><select id="field-category" name="category"><option>Stay</option><option>Travel</option><option>Places & ideas</option><option>Other</option></select>`+area('Notes','notes'),async v=>{const u=new URL(v.url);if(!['https:','http:'].includes(u.protocol))throw Error('Use an http or https link.');await addEntry(kind,v)}],
 poll:['Create poll',field('What should we decide?','title','text','',true)+area('Options (one per line, at least two)','options'),async v=>{const options=[...new Set(v.options.split('\n').map(s=>s.trim()).filter(Boolean))];if(options.length<2||options.length>10)throw Error('Add between 2 and 10 different options.');await addEntry(kind,{title:v.title,options})}]
 };const f=forms[kind];form(...f)}
function renderChatBubble(){const bubble=$('#chat-bubble');if(!bubble)return;const unread=[...chat.unread.values()].reduce((sum,n)=>sum+Number(n||0),0),badge=bubble.querySelector('b');bubble.hidden=!member||state.agreement_required||currentPage==='discussions';badge.hidden=!unread;badge.textContent=unread>99?'99+':String(unread);bubble.setAttribute('aria-label',unread?`Open chat, ${unread} unread message${unread===1?'':'s'}`:'Open chat')}
function renderNav(){const active=tabs.find(t=>t[0]===currentPage)||tabs[0],unread=[...chat.unread.values()].reduce((sum,n)=>sum+Number(n||0),0);$('#nav').innerHTML=tabs.map((t,i)=>`${i===8?'<div class="nav-separator"></div>':''}<a class="nav-link ${t[0]===active[0]?'active':''}" href="#${t[0]}" ${t[0]===active[0]?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${t[1]}</span>${t[2]}${t[0]==='discussions'&&unread?`<span class="nav-count">${unread>99?'99+':unread}</span>`:t[0]==='crew'&&crewCount()?`<span class="nav-count">${crewCount()}</span>`:''}</a>`).join('');$('#page-label').textContent=active[2];renderChatBubble()}
const intro=(eyebrow,title,subtitle,action='')=>`<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="intro-note">${subtitle}</p></div>${action}</div>`;
const empty=(symbol,title,body,button='',action='')=>`<div class="empty"><div class="empty-symbol" aria-hidden="true">${symbol}</div><h3>${title}</h3><p>${body}</p>${button?`<button class="button small light" data-action="${action}">${button} ↗</button>`:''}</div>`;
function deleteButton(e){return (isAdmin()||mine(e))?`<button class="delete-button" data-delete="${e.id}" aria-label="Remove ${esc(e.data.title||'item')}">×</button>`:''}
const palms=`<svg class="palms" viewBox="0 0 300 380" fill="none" aria-hidden="true"><path d="M210 390Q165 245 198 80" stroke="#245f50" stroke-width="14"/><path d="M195 85Q134 14 61 61Q131 47 182 92Q93 68 44 130Q116 100 187 100Q121 112 99 195Q144 128 192 105Q178 163 196 209Q214 148 201 98Q240 149 289 163Q274 110 207 90Q252 61 300 92Q284 31 205 77Q223 20 192 4Q178 39 195 85Z" fill="#245f50"/><path d="M277 389Q254 287 273 206" stroke="#3a7660" stroke-width="9"/><path d="M272 210Q224 167 186 192Q228 185 266 219Q218 207 185 244Q237 226 268 223Q238 249 241 294Q264 259 274 226Q293 270 321 270L305 219Q309 185 274 210Z" fill="#3a7660"/></svg>`;
function overview(){const plans=allPlans();const total=entries('expense').reduce((s,e)=>s+Number(e.data.amount),0);const days=state.trip.start?Math.ceil((new Date(state.trip.start+'T00:00:00')-new Date(new Date().toDateString()))/86400000):null;return intro('THE PLAN IS TO MAKE MEMORIES','A little closer to <span class="soft">Goa.</span>','Big ideas, small details, and everyone in one place.',`<span class="date-chip">◷ &nbsp; ${state.trip.start?date(state.trip.start)+' — '+date(state.trip.end):'Dates are still a blank canvas'}</span>`)+`<section class="hero"><div class="hero-art"><div class="sun"></div><div class="island"></div><div class="wave one"></div><div class="wave two"></div><div class="wave three"></div>${palms}</div><span class="hero-number">01</span><div class="hero-copy"><div class="eyebrow">✦ &nbsp; A LITTLE SUN. A LOT OF STORIES.</div><h2>Good company.<br>Great <em>getaway.</em></h2><p>A space for our plans, our people, and the days we’ll talk about long after Goa.</p><button class="button" data-action="plan">Let’s make a plan <span>↗</span></button></div><div class="hero-caption">MEET ME WHERE THE SEA IS</div></section><div class="stat-grid"><div class="stat"><span class="stat-icon">☀</span><div><div class="stat-label">The countdown</div><div class="stat-value">${days===null?'—':days>0?days:days===0?'Today':'Goa time'}<small>${days>0?'days to go':days===null?'set your dates':''}</small></div></div></div><div class="stat"><span class="stat-icon">♧</span><div><div class="stat-label">Our people</div><div class="stat-value">${state.members.length||'—'}<small>${state.members.length?'in the crew':'invite the crew'}</small></div></div></div><div class="stat"><span class="stat-icon">₹</span><div><div class="stat-label">Trip budget</div><div class="stat-value">${state.trip.budget?money(state.trip.budget):'—'}<small>${state.trip.budget?'total target':'to be decided'}</small></div></div></div><div class="stat"><span class="stat-icon">◷</span><div><div class="stat-label">Plans on the board</div><div class="stat-value">${plans.length}<small>and counting</small></div></div></div></div><div class="two-col"><section class="panel"><div class="panel-head"><h2>A plan in the making</h2><a class="text-link" href="#itinerary">Full itinerary ↗</a></div>${plans.length?plans.slice(0,3).map(planRow).join(''):empty('◷','Every good story starts somewhere.','Add your first stop, a beach day, or just a slow morning.','Add the first plan','add-itinerary')}</section><section class="panel"><div class="panel-head"><h2>Let’s get everyone here</h2><span class="eyebrow" style="font-size:8px">THE CREW</span></div>${state.members.length?state.members.slice(0,3).map(m=>`<div class="row"><span class="avatar">${esc(m.display_name?.[0]||'G')}</span><div class="row-main"><h3>${esc(m.display_name)}</h3><p>${esc(m.role)}</p></div></div>`).join(''):empty('♧','Better with your people.','Invite your travel crew. One shared place, a lot less back-and-forth.','Invite participants','invite')}<div class="callout"><span style="font-size:23px">✳</span><p><strong>Make room for the unplanned.</strong>The best moments rarely need an itinerary.</p></div></section></div><div class="section-grid"><a class="feature-card" href="#polls"><span class="arrow">↗</span><div class="feature-icon">▥</div><h3>Decide it together</h3><p>Beach or backwaters? Put it to a vote.</p></a><a class="feature-card" href="#expenses"><span class="arrow">↗</span><div class="feature-icon">₹</div><h3>Keep the money simple</h3><p>${total?money(total)+' logged so far.':'Shared costs, without the awkward maths.'}</p></a><a class="feature-card" href="#links"><span class="arrow">↗</span><div class="feature-icon">↗</div><h3>Bookings, ready when needed</h3><p>Tickets, stays, transport, and reservations for the right crew members.</p></a></div>`}
const bookingLabels={ticket:'Travel ticket',stay:'Hotel / stay',transport:'Local transport',activity:'Activity / reservation',other:'Other booking'};
function bookingPlans(){return (state.files||[]).filter(f=>f.booking_type&&f.start_date).map(f=>({id:'booking-'+f.id,booking:true,file:f,data:{title:`${bookingLabels[f.booking_type]||'Booking'} · ${f.name}`,date:f.start_date,time:'',location:'',notes:`${f.end_date&&f.end_date!==f.start_date?'Until '+date(f.end_date)+' · ':''}For ${f.members?.map(m=>m.display_name).join(', ')||'selected crew'}`}}))}
function allPlans(){return [...entries('itinerary'),...bookingPlans()].sort((a,b)=>((a.data.date||'')+' '+(a.data.time||'')).localeCompare((b.data.date||'')+' '+(b.data.time||'')))}
function planRow(e){return `<div class="row"><span class="time-stamp">${esc(e.data.time||'TBD')}</span><div class="row-main"><h3>${esc(e.data.title)}${e.booking?' <span class="row-badge">Booking</span>':''}</h3><p>${date(e.data.date)}${e.data.location?' · '+esc(e.data.location):''}${e.data.notes?'\n'+esc(e.data.notes):''}</p></div>${e.booking?`<button class="button small outline" data-download="${e.file.id}">↓ File</button>`:deleteButton(e)}</div>`}
function itinerary(){const list=allPlans();return intro('THE DAYS AHEAD','Leave a little room for magic.','Plans and personal bookings appear together automatically.',`<button class="button" data-action="add-itinerary">＋ Add a plan</button>`)+`<section class="panel full-panel">${list.length?list.map(planRow).join(''):empty('◷','No plans. Endless possibilities.','Add a plan or upload a booking to place it on the itinerary.','Add a plan','add-itinerary')}</section>`}
function discussions(){if(!live){const list=entries('message');return intro('THE GROUP CHAT, WITH A VIEW','Talk trip to me.','Ideas, questions, and those “what if we…” moments.')+`<section class="panel"><div class="chat-feed">${list.length?list.map(e=>`<article class="message ${mine(e)?'mine':''}"><div class="author">${esc(e.data.author||'Crew member')}</div><p>${esc(e.data.text)}</p><time>${new Date(e.created_at).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time>${deleteButton(e)}</article>`).join(''):empty('☏','The conversation starts with you.','Drop an idea or ask the crew a question.')}</div><form id="chat-form" class="chat-form"><input name="text" aria-label="Your message" placeholder="What’s on your Goa wishlist?" maxlength="4000" required><button class="button" type="submit">Send ↗</button></form><p class="note">Personal preview: messages are saved in this browser only.</p></section>`}const others=state.members.filter(m=>m.user_id!==session?.user?.id);if(chat.peerId&&!others.some(m=>m.user_id===chat.peerId))chat.peerId=null;const peer=chat.peerId?chatMember(chat.peerId):null,messages=conversationMessages(),key=chatKey(chat.peerId),loading=chat.loading.has(key)&&!chat.loaded.has(key);markChatRead();const roomName=peer?peer.display_name:'Main group chat',roomStatus=peer?(chatPresence(peer.user_id).active?'Active now':'Offline'):`${state.members.length} member${state.members.length===1?'':'s'}`,pending=chat.pendingFile?`<div class="chat-pending-file"><span>${esc(chat.pendingFile.name)}</span><small>${fileSize(chat.pendingFile.size)}</small><button type="button" data-chat-remove-file aria-label="Remove selected attachment">×</button></div>`:'';return intro('LIVE TRIP CONVERSATIONS',peer?'Private conversation.':'The group chat, with a view.',peer?`Only you and ${esc(peer.display_name)} can see these messages.`:'Every invited trip member can chat and plan here.')+`<div class="chat-layout ${chat.roomOpen?'room-open':'list-open'}"><aside class="panel conversation-list" aria-label="Conversations"><div class="conversation-heading">Conversations <span id="chat-live-status" class="live-status ${chat.connected?'':'offline'}">${chat.connected?'Live':'Reconnecting…'}</span></div><button class="conversation-button ${!peer?'active':''}" data-chat-peer=""><span class="conversation-avatar group">☏</span><span><strong>Main group</strong><small>Everyone on this trip</small></span></button><div class="conversation-label">Direct messages</div>${others.length?others.map(m=>{const p=chatPresence(m.user_id);return `<button class="conversation-button ${peer?.user_id===m.user_id?'active':''}" data-chat-peer="${m.user_id}"><span class="conversation-avatar">${esc(m.display_name?.[0]||'G')}<i class="presence-dot ${p.active?'active':''}" data-presence-id="${m.user_id}" data-presence-kind="dot"></i></span><span><strong>${esc(m.display_name)}</strong><small data-presence-id="${m.user_id}" data-presence-kind="text">${p.active?'Active now':'Offline'}</small></span></button>`}).join(''):'<p class="note">Invite another crew member to start a private chat.</p>'}</aside><section class="panel chat-room"><div class="chat-room-head"><button class="chat-back" type="button" data-chat-list aria-label="Back to conversations">←</button><span class="conversation-avatar ${peer?'':'group'}">${peer?esc(peer.display_name?.[0]||'G'):'☏'}${peer?`<i class="presence-dot ${chatPresence(peer.user_id).active?'active':''}" data-presence-id="${peer.user_id}" data-presence-kind="dot"></i>`:''}</span><div><h2>${esc(roomName)}</h2><p ${peer?`data-presence-id="${peer.user_id}" data-presence-kind="text"`:''}>${esc(roomStatus)}</p></div></div><div class="chat-feed" id="chat-feed" aria-live="polite">${loading?'<div class="chat-loading">Loading conversation…</div>':messages.length?messages.map(chatMessageHtml).join(''):empty('☏',peer?'Say hello privately.':'The conversation starts with you.',peer?`Message ${esc(peer.display_name)}. Only the two of you can read this chat.`:'Drop an idea or ask the whole crew a question.')}</div><div id="typing-indicator" class="typing-indicator" aria-live="polite">${esc(chatTypingText())}</div><form id="chat-form" class="chat-form"><input id="chat-file" type="file" hidden accept=".pdf,.jpg,.jpeg,.png,.webp,.heic,.txt,.csv,.json,.docx,.xlsx"><button type="button" class="chat-attach-button" data-chat-attach aria-label="Attach a picture or file">${attachIcon}</button><div class="chat-compose-main">${pending}<input name="text" aria-label="Message ${esc(roomName)}" placeholder="${peer?'Message '+esc(peer.display_name)+'…':'Message the trip crew…'}" value="${esc(chat.draft)}" maxlength="4000" autocomplete="off"></div><button class="button" type="submit">Send ↗</button></form><p class="note">Messages and attachments update live. Direct messages stay between the two participants.</p></section></div>`}
function polls(){const list=entries('poll');return intro('FEWER MAYBES, MORE MEMORIES','Good ideas. Group decisions.','One vote per person on each poll. Change your mind anytime.',`<button class="button" data-action="add-poll">＋ Create a poll</button>`)+`${list.length?list.map(e=>{const vs=state.votes.filter(v=>v.entry_id===e.id);const own=vs.find(v=>v.user_id===(session?.user?.id||'local'));return `<section class="panel poll-card"><div class="panel-head"><h2>${esc(e.data.title)}</h2>${deleteButton(e)}</div>${e.data.options.map((o,i)=>{const n=vs.filter(v=>v.option_index===i).length;return `<button class="poll-option ${own?.option_index===i?'selected':''}" data-vote="${e.id}" data-option="${i}" aria-pressed="${own?.option_index===i}"><span class="poll-fill" style="width:${vs.length?n/vs.length*100:0}%"></span><span>${esc(o)} ${own?.option_index===i?'✓':''}</span><span>${n} vote${n!==1?'s':''}</span></button>`}).join('')}<p class="note">${vs.length} crew member${vs.length!==1?'s':''} voted</p></section>`}).join(''):`<section class="panel">${empty('▥','Decisions are better together.','Create a poll for dates, stays, activities, or whatever the group needs to decide.','Create a poll','add-poll')}</section>`}`}
function expenses(){const list=entries('expense'),bills=new Map((state.expense_bills||[]).map(b=>[b.entry_id,b])),people=new Map(expensePeople().map(p=>[p.key,p])),total=list.reduce((s,e)=>s+Number(e.data.amount),0),paid={};const payerName=e=>people.get(e.data.payer_key)?.display_name||state.members.find(m=>m.user_id===e.data.payer_id)?.display_name||e.data.payer||'Crew member';list.forEach(e=>{const p=payerName(e);paid[p]=(paid[p]||0)+Number(e.data.amount)});return intro('LESS MATHS. MORE MOMENTS.','Keep tabs. Keep it easy.','Choose who paid, split it with everyone or selected crew, and keep the bill nearby.',`<button class="button" data-action="add-expense">＋ Add expense</button>`)+`<div class="two-col"><section class="panel"><div class="eyebrow">TOTAL LOGGED</div><div class="summary-total">${money(total)}</div><p class="muted">${state.trip.budget?'Trip target: '+money(state.trip.budget):'Set a total trip budget in settings.'}</p></section><section class="panel"><div class="eyebrow">PAID BY</div>${Object.keys(paid).length?Object.entries(paid).map(([p,a])=>`<div class="row expense-paid-row"><span class="avatar">${esc(p[0]||'₹')}</span><span class="row-main">${esc(p)}</span><strong>${money(a)}</strong></div>`).join(''):'<p class="intro-note">Your shared spending will appear here.</p>'}</section></div><section class="panel expense-list">${list.length?list.map(e=>{const bill=bills.get(e.id),previewable=bill&&/^(image\/|application\/pdf|text\/|application\/json)/.test(bill.mime_type||''),split=Array.isArray(e.data.split_with)?e.data.split_with:[],share=split.length?Number(e.data.amount)/split.length:0;return `<article class="row expense-row"><span class="stat-icon">₹</span><div class="row-main"><h3>${esc(e.data.title)}</h3><p>Paid by ${esc(payerName(e))}${e.data.notes?' · '+esc(e.data.notes):''}</p>${split.length?`<div class="expense-split-summary"><strong>Split with ${split.length===crewCount()?'everyone':split.length+' '+(split.length===1?'person':'people')} · ${shareMoney(share)} each</strong><span>${split.map(p=>esc(p.name)).join(', ')}</span></div>`:'<div class="expense-split-summary unsplit"><strong>Split not recorded</strong><span>This expense was added before split tracking.</span></div>'}${bill?`<div class="expense-bill"><span class="expense-file-icon">${bill.mime_type?.startsWith('image/')?'▧':'↗'}</span><span><strong>${esc(bill.name)}</strong><small>${fileSize(Number(bill.size_bytes)||0)}</small></span>${previewable?`<button type="button" class="text-link" data-expense-preview="${e.id}">Preview</button>`:''}<button type="button" class="text-link" data-expense-download="${e.id}">Download</button></div>`:''}</div><strong class="expense-amount">${money(e.data.amount)}</strong>${deleteButton(e)}</article>`}).join(''):empty('₹','A clean slate.','Add costs as they happen: travel, stays, food, and everything in between.','Log an expense','add-expense')}</section><p class="note">Splits are recorded for planning only. The app does not collect payments or settle balances.</p>`}
function checklist(){const list=entries('checklist');return intro('THE LITTLE THINGS, COVERED','Ready, set, Goa.','From tickets to sunscreen. Give every detail a home.',`<button class="button" data-action="add-checklist">＋ Add an item</button>`)+`<section class="panel">${list.length?list.map(e=>`<div class="row"><label class="check-target"><input class="check" type="checkbox" aria-label="Complete ${esc(e.data.title)}" data-check="${e.id}" ${e.data.done?'checked':''}></label><div class="row-main"><h3 class="${e.data.done?'done':''}">${esc(e.data.title)}</h3><p>${esc(e.data.category)}${e.data.assignee?' · '+esc(e.data.assignee):''}</p></div>${deleteButton(e)}</div>`).join(''):empty('☑','Nothing forgotten. Nobody guessing.','Add shared to-dos, packing essentials, and pre-trip reminders.','Add an item','add-checklist')}</section>`}
function safeUrl(v){try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}}
function bookingDates(f){if(!f.start_date)return 'No date added';if(f.booking_type==='stay'&&f.end_date)return `${date(f.start_date)} — ${date(f.end_date)}`;return date(f.start_date)}
function storagePanel(){const files=state.files||[];return `<section class="panel booking-panel"><div class="panel-head"><div><h2>${files.length?'Your bookings':'Keep every confirmation handy'}</h2><p class="muted">Private to the selected travellers and trip admins.</p></div><button class="button small" data-action="upload">＋ Add booking</button></div>${files.length?files.map(f=>`<div class="row booking-row"><span class="stat-icon">↗</span><div class="row-main"><h3>${esc(f.name)}</h3><p>${esc(bookingLabels[f.booking_type]||'Booking')} · ${esc(bookingDates(f))} · ${(f.size_bytes/1024/1024).toFixed(2)} MB</p><div class="booking-people">${(f.members||[]).map(m=>`<span>${esc(m.display_name)}</span>`).join('')}</div></div><button class="button small outline" data-download="${f.id}">↓ Download</button>${isAdmin()||f.uploaded_by===session?.user?.id?`<button class="delete-button" data-remove-file="${f.id}" aria-label="Remove ${esc(f.name)}">×</button>`:''}</div>`).join(''):`<div class="booking-empty"><span class="booking-empty-icon">↗</span><h3>Nothing uploaded yet</h3><p>Add a ticket, hotel confirmation, transport booking, or activity reservation. Choose the travellers once and it appears in the right itineraries automatically.</p><div class="booking-privacy-note"><span>✓</span><span><strong>Shared with the right people only</strong><small>Unselected crew members cannot open or download the document.</small></span></div></div>`}</section>`}
function links(){return intro('BOOKED AND READY','Bookings, without the group-chat hunt.','One private place for tickets, stays, transport, and reservations.')+`<div class="booking-type-strip"><span><b>✈</b> Travel tickets</span><span><b>⌂</b> Hotels & stays</span><span><b>↗</b> Transport</span><span><b>✦</b> Activities</span></div>`+storagePanel()}
function crew(){const manual=state.manual_crew||[],actions=isAdmin()?`<div class="section-actions"><button class="button" data-action="invite">↗ Invite participant</button><button class="button outline" data-action="add-manual-crew">＋ Add expense-only crew</button></div>`:'';return intro('YOUR FAVOURITE TRAVEL COMPANIONS','The people make the trip.','Account members can chat and open private bookings. Expense-only crew can still be included in shared costs.',actions)+`<section class="panel"><div class="panel-head"><div><h2>Connected crew</h2><p class="muted">Members who can sign in to the trip.</p></div></div>${state.members.length?`<div class="people-grid">${state.members.map(m=>{const self=m.user_id===session?.user?.id,p=chatPresence(m.user_id),owner=!!m.is_owner,identity=`<span class="avatar">${esc(m.display_name?.[0]||'G')}${!self?`<i class="presence-dot ${p.active?'active':''}" data-presence-id="${m.user_id}" data-presence-kind="dot"></i>`:''}</span><span class="person-details"><strong>${esc(m.display_name)}${owner?' <em class="owner-badge">Owner</em>':m.role==='admin'?' <em class="admin-badge">Admin</em>':''}</strong><small>${self?`${owner?'owner':esc(m.role)} · you`:p.active?'Active now':'Offline'}</small></span>`;const controls=isAdmin()&&!self&&!owner?`<div class="crew-controls"><button class="text-link role-button" data-member-role="${m.user_id}" data-next-role="${m.role==='admin'?'participant':'admin'}">${m.role==='admin'?'Remove admin access':'Make admin'}</button>${m.role==='participant'?`<button class="delete-button" data-remove-member="${m.user_id}" aria-label="Remove ${esc(m.display_name)} from trip">×</button>`:''}</div>`:'';return `<div class="person-card">${self?identity:`<button class="person-chat" data-chat-user="${m.user_id}" aria-label="Message ${esc(m.display_name)}">${identity}</button>`}${controls}</div>`}).join('')}</div>`:empty('♧','Your connected crew belongs here.','Invite participants who will use the trip app.','Invite the crew','invite')}</section><section class="panel manual-crew-panel"><div class="panel-head"><div><h2>Expense-only crew</h2><p class="muted">Add people who will not create an account but should be included in expense splits.</p></div>${isAdmin()?'<button class="button small outline" data-action="add-manual-crew">＋ Add person</button>':''}</div>${manual.length?`<div class="people-grid">${manual.map(m=>`<div class="person-card manual-person"><span class="avatar">${esc(m.display_name?.[0]||'G')}</span><span class="person-details"><strong>${esc(m.display_name)} <em class="guest-badge">Expense-only</em></strong><small>No login · available in expense splits</small></span>${isAdmin()?`<button class="delete-button" data-remove-manual="${m.id}" aria-label="Remove ${esc(m.display_name)} from expense crew">×</button>`:''}</div>`).join('')}</div>`:'<div class="manual-crew-empty"><span>₹</span><div><strong>No expense-only crew yet</strong><p>Add someone here when they need to be included in costs without using the app.</p></div></div>'}</section>${isAdmin()&&live?'<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Pending invitations</h2><button class="text-link" id="load-invites">Show invitations ↗</button></div><div id="invite-list"></div></section>':''}`}
function settings(){const t=state.trip;return intro('MAKE IT YOURS','A trip with your name on it.','Start from scratch. Fill in the details when you know them.')+`<section class="panel settings-card"><div class="panel-head"><h2>Trip essentials</h2>${!isAdmin()?'<span class="row-badge">Admin managed</span>':''}</div><form id="settings-form"><fieldset ${!isAdmin()?'disabled':''} style="border:0;padding:0;margin:0">${field('Trip name','title','text',t.title,true)}${field('Departing from','departure','text',t.departure)}<div class="field-pair">${field('Start date','start','date',t.start)}${field('End date','end','date',t.end)}</div>${field('Total trip budget (INR)','budget','number',t.budget)}${area('The big picture: travel, stay, ideas, or anything the crew should know','notes',t.notes)}${isAdmin()?'<div class="form-actions"><button class="button" type="submit">Save trip details ↗</button></div>':''}</fieldset></form></section><section class="panel settings-card" style="margin-top:20px"><div class="panel-head"><h2>Crew privacy &amp; permissions</h2></div><p class="muted">Review the private-crew guidelines, essential storage notice, and optional app permissions you saw when joining.</p><button class="button outline" data-action="agreement" style="margin-top:16px">Review crew agreement</button></section><section class="panel settings-card" style="margin-top:20px"><div class="panel-head"><h2>Keep a copy</h2></div><p class="muted">Download the trip as a JSON file before the temporary site is removed.</p><div class="section-actions" style="margin-top:16px"><button class="button outline" data-action="export">↓ Export trip data</button><button class="button outline" data-action="motion">Toggle animations</button></div>${!live?'<p class="note">Personal preview data stays in this browser. It will not automatically transfer to Supabase.</p>':''}</section>${!live?'<section class="panel settings-card" style="margin-top:20px"><div class="panel-head"><h2>A fresh start</h2></div><p class="muted">Clear the trip details saved in this browser.</p><button class="button outline" data-action="reset" style="margin-top:16px">Clear personal preview</button></section>':''}`}
function welcome(){return intro('THE NEXT CHAPTER STARTS HERE','Your people. Your plans. Your Goa.','An invitation-only escape, with everything in one happy place.')+`<section class="hero"><div class="hero-art"><div class="sun"></div><div class="island"></div><div class="wave one"></div><div class="wave two"></div><div class="wave three"></div>${palms}</div><span class="hero-number">01</span><div class="hero-copy"><div class="eyebrow">✦ &nbsp; A LITTLE SUN. A LOT OF STORIES.</div><h2>Good company.<br>Great <em>getaway.</em></h2><p>Our own little corner for a trip we’ll remember. Sign in, bring your ideas, and let’s find our way to the coast.</p><button class="button" data-action="account">${session?'Your account':'Join your crew'} ↗</button></div><div class="hero-caption">MEET ME WHERE THE SEA IS</div></section><section class="panel" style="margin-top:22px">${empty('♧',session?'You’re signed in. Let’s get you in.':'Good times are invitation only.',session?'Reopen your invitation link or ask your trip admin for a new invitation.':'Open your invitation link, enter your email or mobile number, and choose a password. Already joined? Sign in to find your crew.','Open account','account')}</section>`}
const phoneCountries=[['+91','India'],['+1','US / Canada'],['+44','United Kingdom'],['+971','UAE'],['+61','Australia'],['+65','Singapore'],['+49','Germany'],['+33','France'],['+81','Japan'],['+974','Qatar'],['+966','Saudi Arabia'],['+968','Oman'],['+973','Bahrain'],['+965','Kuwait'],['+60','Malaysia'],['+64','New Zealand'],['+27','South Africa']];
function phoneField(label='WhatsApp number',key='phone',value=''){let code='+91',number=value;if(value.startsWith('+')){const match=[...phoneCountries].sort((a,b)=>b[0].length-a[0].length).find(([c])=>value.startsWith(c));if(match){code=match[0];number=value.slice(code.length)}}return `<label for="field-${key}">${esc(label)}</label><div class="phone-input"><select name="${key}_country" aria-label="Country code for ${esc(label)}">${phoneCountries.map(([c,n])=>`<option value="${c}" ${code===c?'selected':''}>${n} (${c})</option>`).join('')}</select><input id="field-${key}" name="${key}" type="tel" autocomplete="tel-national" inputmode="tel" value="${esc(number)}" placeholder="WhatsApp mobile number" maxlength="24" required></div>`}
function phoneValue(form,key='phone'){const raw=String(form.elements[key].value||'').trim(),digits=raw.replace(/[\s()-]/g,'');const number=digits.startsWith('+')?digits:String(form.elements[key+'_country'].value)+digits;if(!/^\+[1-9]\d{7,14}$/.test(number))throw Error('Enter a valid WhatsApp number and country code.');return number}
function authPage(){const signup=authMode==='signup',invited=!!sessionStorage.getItem('goa-invite'),codeStep=!!otpPending,adminSetup=signup&&window.GOA_INVITE_INFO?.role==='admin';return `<div class="auth-layout"><section class="auth-visual"><a class="brand auth-brand" href="#login"><span class="brand-sun">✳</span><span>afterglow<small>THE GOA EDITION</small></span></a><div class="auth-art"><div class="sun"></div><div class="wave one"></div><div class="wave two"></div><div class="wave three"></div>${palms}</div><div class="auth-story"><div class="eyebrow">OUR OWN LITTLE ESCAPE</div><h2>Goa is better<br>together.</h2><p>The plans. The people. The memories.<br>Your crew’s private corner of the coast.</p></div><span class="auth-location">GOA, INDIA &nbsp; ✳ &nbsp; GOOD TIMES AHEAD</span></section><section class="auth-main"><div class="auth-card"><div class="eyebrow">PRIVATE CREW SPACE</div><h1>${codeStep?'Check your WhatsApp.':signup?'Your profile is ready.':'Welcome back.'}</h1><p class="intro-note">${codeStep?'Enter the six-digit code sent to '+esc(otpPending.hint)+'.':signup?'Verify the WhatsApp number on your invitation, then review and accept the crew terms.':'Sign in to your Goa trip.'}</p>${!codeStep?`<div class="auth-tabs" role="group" aria-label="Account options"><button type="button" data-auth-mode="login" class="${!signup?'selected':''}">Log in</button><button type="button" data-auth-mode="signup" class="${signup?'selected':''}">Activate invite</button></div>`:''}<form id="auth-page-form">${codeStep?'<label for="otp-code">WhatsApp verification code</label><input id="otp-code" name="code" autocomplete="one-time-code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="6-digit code" required><p class="note">Codes expire in five minutes. Never share your code.</p>':`${!signup?'<div class="auth-method"><button type="button" data-auth-method="whatsapp" class="'+(authMethod==='whatsapp'?'selected':'')+'">WhatsApp code</button><button type="button" data-auth-method="password" class="'+(authMethod==='password'?'selected':'')+'">Password</button></div>':''}${signup&&!invited?field('Invitation link or code','invitation','text','',true):''}${adminSetup?field('Your name','display_name','text',authName||window.GOA_INVITE_INFO?.label||'',true):''}${signup?'<p class="note">'+(invited?'Your name and crew profile were prepared by the trip admin.':'Paste the private invitation link sent to your WhatsApp number.')+'</p>':''}${signup||authMethod==='whatsapp'?phoneField('WhatsApp number','phone',authPhone||window.GOA_INVITE_INFO?.phone||''):field('Email or mobile number','contact','text',authContact,true)}${adminSetup?field('Admin email','email','email',window.GOA_INVITE_INFO?.contact||authContact,true):''}${adminSetup||(!signup&&authMethod==='password')?'<label for="auth-password">Password</label><input name="password" id="auth-password" type="password" autocomplete="'+(signup?'new-password':'current-password')+'" minlength="10" maxlength="128" required><p class="note">'+(signup?'Use at least 10 characters for the initial admin account.':'Use the password created with this account.')+'</p>':'<p class="note">We’ll send a one-time login code to the invited WhatsApp number.</p>'}`}<div id="auth-error" class="error" role="alert" ${authError?'':'hidden'}>${esc(authError)}</div><button class="button auth-submit" type="submit">${codeStep?'Verify and continue':signup?'Send login code':authMethod==='whatsapp'?'Send WhatsApp code':'Log in'} ↗</button></form>${codeStep?'<p class="auth-switch"><button type="button" id="otp-back">Use another number or request a new code</button></p>':`<p class="auth-switch">${signup?'Already activated? <button type="button" data-auth-mode="login">Log in</button>':'Have an invitation? <button type="button" data-auth-mode="signup">Activate it</button>'}</p>`}<p class="auth-privacy">♧ &nbsp; Only invited members can access trip details.</p></div></section></div>`}
function invitationToken(value){const raw=String(value||'').trim();if(/^[a-f0-9]{64}$/i.test(raw))return raw;try{const u=new URL(raw),allowed=[location.origin,new URL(config.appUrl).origin,'https://goa-afterglow-trip.clever-sky-9771.chatgpt.site'];if(!allowed.includes(u.origin))throw Error();const token=u.hash.startsWith('#join=')?u.hash.slice(6):u.searchParams.get('invite');if(/^[a-f0-9]{64}$/i.test(token||''))return token}catch{}throw Error('Paste a valid invitation link or code from your trip admin.')}
async function inspectInvitation(token){const info=await api('inspectInvite',{invite:token});if(info.trip_id!==config.tripId)throw Error('This invitation is for a different trip.');sessionStorage.setItem('goa-invite',token);window.GOA_INVITE_INFO=info;return info}
async function finishAuthentication(result){otpPending=null;authPhone='';saveSession(result);sessionStorage.removeItem('goa-invite');window.GOA_INVITE_INFO=null;otpPending=null;authError='';authContact='';authName='';authPhone='';currentPage='overview';history.replaceState(null,'',location.pathname+location.search+'#overview');await sync();toast('Welcome to your Goa escape.')}
function bindAuth(){
 const switchView=fn=>{if(authBusy)return;const form=$('#auth-page-form');if(form){authContact=form.elements.contact?.value||form.elements.email?.value||authContact;authName=form.elements.display_name?.value||authName;if(form.elements.phone){try{authPhone=phoneValue(form)}catch{}}}otpPending=null;authError='';fn();render()};
 document.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>switchView(()=>authMode=b.dataset.authMode));document.querySelectorAll('[data-auth-method]').forEach(b=>b.onclick=()=>switchView(()=>authMethod=b.dataset.authMethod));if($('#otp-back'))$('#otp-back').onclick=()=>switchView(()=>{});
 $('#auth-page-form').onsubmit=e=>{e.preventDefault();if(authBusy)return;const form=e.target,data=Object.fromEntries(new FormData(form));authBusy=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);const error=$('#auth-error');error.hidden=true;
 (async()=>{try{
  if(otpPending){const result=await api('verifyOtp',{challenge_id:otpPending.id,phone:otpPending.phone,code:data.code});await finishAuthentication(result)}
  else if(authMode==='login'&&authMethod==='password'){await finishAuthentication(await api('login',{contact:data.contact,password:data.password,invite:sessionStorage.getItem('goa-invite')||''}))}
  else{const phone=phoneValue(form);authPhone=phone;const request={phone,purpose:authMode==='signup'?'signup':'login'};if(authMode==='signup'){const token=invitationToken(sessionStorage.getItem('goa-invite')||data.invitation);await inspectInvitation(token);Object.assign(request,{invite:token,display_name:data.display_name,email:data.email,password:data.password});authName=data.display_name;authContact=data.email}const result=await api('requestOtp',request);form.reset();otpPending={id:result.challenge_id,phone,hint:result.phone_hint};authError='';render()}
 }catch(err){authError=err.message;error.textContent=authError;error.hidden=false}finally{authBusy=false;form.querySelectorAll('button').forEach(b=>b.disabled=false)}})();
 };
}
