 document.querySelectorAll('[data-poll-custom]').forEach(formEl=>formEl.onsubmit=e=>{e.preventDefault();const input=formEl.elements.answer;run(async()=>{await customPollVote(formEl.dataset.pollCustom,input.value);input.value=''})});
 document.querySelectorAll('[data-remove-member]').forEach(b=>b.onclick=()=>removeMember(b.dataset.removeMember));
