const bookingTypes=[['ticket','Flight, train or bus ticket'],['stay','Hotel or stay'],['transport','Local transport'],['activity','Activity or reservation'],['other','Other trip document']];
function bookingDateFields(type){if(type==='stay')return `<div class="booking-date-grid"><div><label for="booking-start">Check-in</label><input id="booking-start" name="start_date" type="date" required></div><div><label for="booking-end">Check-out</label><input id="booking-end" name="end_date" type="date" required></div></div>`;const labels={ticket:'Travel date',transport:'Pickup / travel date',activity:'Reservation date',other:'Document date (optional)'};return `<label for="booking-start">${labels[type]||'Date'}</label><input id="booking-start" name="start_date" type="date" ${type==='other'?'':'required'}><input name="end_date" type="hidden" value="">`}
async function uploadFile(){if(!canWrite())return openAccount();if(!live)return toast('Uploads are available on the connected website.');const currentId=session?.user?.id;openModal('Upload a booking',`<p class="modal-note">Choose the booking type and everyone it belongs to. The document and its itinerary details will be private to those crew members and trip admins. Maximum 10 MB.</p><form id="upload-form"><label for="booking-type">Booking type</label><select name="booking_type" id="booking-type">${bookingTypes.map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select><div id="booking-dates">${bookingDateFields('ticket')}</div><fieldset class="booking-member-fieldset"><legend>Who is this booking for?</legend><p class="muted">Select every person named on the ticket, room, or reservation.</p><div class="booking-member-grid">${(state.members||[]).map(m=>`<label class="booking-member"><input type="checkbox" name="member_ids" value="${m.user_id}" ${m.user_id===currentId?'checked':''}><span>${esc(m.display_name)}${m.user_id===currentId?' · You':''}</span></label>`).join('')}</div></fieldset><label for="upload-file">Booking document</label><input id="upload-file" type="file" name="file" required accept=".pdf,.jpg,.jpeg,.png,.webp,.heic,.txt,.docx"><div class="form-actions"><button class="button outline" type="button" data-close>Cancel</button><button class="button" type="submit">Upload booking ↗</button></div></form>`);const formEl=$('#upload-form'),typeEl=$('#booking-type');typeEl.onchange=()=>{$('#booking-dates').innerHTML=bookingDateFields(typeEl.value)};formEl.onsubmit=e=>{e.preventDefault();run(async()=>{const selected=[...formEl.querySelectorAll('input[name="member_ids"]:checked')].map(x=>x.value);if(!selected.length)throw Error('Select at least one crew member for this booking.');if(!isAdmin()&&!selected.includes(currentId))selected.push(currentId);const f=formEl.file.files[0];if(!f||f.size>10485760)throw Error('Choose a file no larger than 10 MB.');const values=new FormData(formEl),start=values.get('start_date')||null,end=values.get('end_date')||null;if(typeEl.value==='stay'&&end<start)throw Error('Check-out must be on or after check-in.');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f)});const fallback=f.name.toLowerCase().endsWith('.heic')?'image/heic':'application/octet-stream';await api('upload',{booking_type:typeEl.value,start_date:start,end_date:end,member_ids:selected,name:f.name,mime_type:f.type||fallback,base64});await sync();closeModal();toast('Booking uploaded and added to the selected itineraries.')})}}
function removeFile(id){const file=state.files.find(f=>f.id===id);if(!file)return;openModal('Remove this booking?',`<p class="modal-note">“${esc(file.name)}” will be removed from the trip for the selected crew members. Other bookings stay in place.</p><div class="form-actions"><button class="button outline" data-close>Keep booking</button><button class="button danger" id="confirm-remove">Remove booking</button></div>`);$('#confirm-remove').onclick=()=>run(async()=>{await api('deleteFile',{id});await sync();closeModal();toast('Booking removed.')})}
async function downloadFile(id){try{const r=await fetch(config.supabaseUrl+'/functions/v1/goa-trip-api',{method:'POST',headers:{apikey:config.supabaseKey,'Content-Type':'application/json',Authorization:'Bearer '+session.access_token},body:JSON.stringify({action:'download',data:{id}})});if(!r.ok)throw Error((await r.json()).error||'Download failed');const blob=await r.blob(),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=state.files.find(f=>f.id===id)?.name||'trip-file';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message)}}
$('#mobile-menu').onclick=()=>window.GOA_LAYOUT?.toggleMenu();$('#invite-top').onclick=invite;$('#account').onclick=openAccount;$('#chat-bubble').onclick=openChatList;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
window.addEventListener('hashchange',async()=>{if(currentPage==='discussions'&&location.hash!=='#discussions'){sendTyping(false);chat.roomOpen=false;chat.peerId=null}if(captureInvite()){authMode='signup';if(session){toast('Sign out to use an invitation for a different account.');return}try{await inspectInvitation(sessionStorage.getItem('goa-invite'));authError=''}catch(e){sessionStorage.removeItem('goa-invite');authError=e.message}render();return}if(!member){authMode=location.hash==='#signup'?'signup':'login'}currentPage=location.hash.slice(1)||'overview';window.GOA_LAYOUT?.closeMenu();render();window.scrollTo({top:0,behavior:'instant'})});
document.addEventListener('visibilitychange',()=>{if(document.hidden){sendTyping(false);disconnectChat()}else if(member)connectChat()});
if(localStorage.getItem('goa-reduce-motion')==='true')document.body.classList.add('motion-off');
function captureInvite(){const hash=location.hash.slice(1);const params=new URLSearchParams(location.search);const token=hash.startsWith('join=')?hash.slice(5):params.get('invite');if(token){sessionStorage.setItem('goa-invite',token);params.delete('invite');history.replaceState(null,'',location.pathname+(params.size?'?'+params:'')+'#signup');return true}return false}
window.GOA_APP={api,getSession:()=>session,getMember:()=>member,toast,openModal,closeModal};
const hasInvite=captureInvite();
if(hasInvite||location.hash==='#signup')authMode='signup';
currentPage=location.hash.slice(1)||'overview';
let initiallySynced=false;
if(live){try{session=JSON.parse(localStorage.getItem('goa-custom-session-v3')||sessionStorage.getItem('goa-custom-session-v2'));if(session&&session.expires_at*1000>Date.now()){saveSession(session);await sync();initiallySynced=true}else saveSession(null)}catch(e){toast(e.message)}syncTimer=setInterval(()=>{const editing=document.activeElement?.matches?.('input,textarea,select');if(!document.hidden&&!$('#modal').open&&!editing)sync().catch(e=>toast(e.message))},15000)}
if(!initiallySynced)render();
showStorageConsent();
if(hasInvite&&live&&!session){try{await inspectInvitation(sessionStorage.getItem('goa-invite'));authError=''}catch(e){sessionStorage.removeItem('goa-invite');authError=e.message}render()}

